fun <T> Flow<T>.myBuffer(n: Int): Flow<T> = flow {
    coroutineScope {
        val slots = Channel<T>(n)
        launch {                                   // 1. a second coroutine runs the upstream
            try { collect { slots.send(it) } }     //    send waits only when all n slots are full
            finally { slots.close() }              // 2. lets the loop below end
        }
        for (value in slots) emit(value)           // 3. our coroutine hands each value on
    }
}
// myBuffer(3): 3 on the belt + 1 in hand = 4 emits return.
// myBuffer(3).myBuffer(3): your function doesn't fuse, so it is two belts and three coroutines.
// The middle coroutine holds one value too: 3 + 1 + 3 + 1 = 8. The library's buffer(3).buffer(3)
// fuses into one channel of 6 slots, so 7.

